wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm::infer;

struct Node;

const SYSTEM: &str = "\
You are a feed-item classifier. Read the item and reply with exactly two \
lines.\n\
Line 1: one of KEEP or DROP.\n\
Line 2: one of RELEASE, SECURITY, RESEARCH, TOOLING, DISCUSSION, OTHER.\n\
If KEEP, you may add a third line: one of MUST_READ, WORTH_A_LOOK, SKIP.\n\
Reply with nothing else.";

fn parse_category(s: &str) -> Category {
    match s.trim().to_ascii_uppercase().as_str() {
        "RELEASE" => Category::Release,
        "SECURITY" => Category::Security,
        "RESEARCH" => Category::Research,
        "TOOLING" => Category::Tooling,
        "DISCUSSION" => Category::Discussion,
        _ => Category::Other,
    }
}

fn parse_importance(s: &str) -> Importance {
    match s.trim().to_ascii_uppercase().as_str() {
        "MUST_READ" | "MUSTREAD" | "MUST-READ" => Importance::MustRead,
        "SKIP" => Importance::Skip,
        _ => Importance::WorthALook,
    }
}

impl Guest for Node {
    fn run(item: FeedItem) -> Classification {
        // The model is the one authority this node holds. It can influence the
        // decision but cannot act: `inference-llm` returns a string and nothing
        // else, so the worst a hostile item can do is steer its own verdict
        // within the closed Category / Importance sets.
        let prompt = format!(
            "feed: {}\ntitle: {}\nlink: {}\npublished: {}\ntext: {}",
            item.feed, item.title, item.link, item.published, item.text
        );

        let reply = infer(SYSTEM, &prompt, "classify");

        let mut lines = reply.lines();
        let verdict = lines.next().unwrap_or("").trim().to_ascii_uppercase();
        let category = parse_category(lines.next().unwrap_or("OTHER"));

        if verdict.starts_with("KEEP") {
            let importance = parse_importance(lines.next().unwrap_or("WORTH_A_LOOK"));
            Classification::Keep(ClassifiedItem {
                item,
                category,
                importance,
            })
        } else {
            Classification::Drop(DroppedItem { item, category })
        }
    }
}

export!(Node);
```

